function replaceExact(source, from, to, label) {
  if (source.includes(to) && !source.includes(from)) return source;
  const first = source.indexOf(from);
  const last = source.lastIndexOf(from);
  if (first < 0 || first !== last) {
    throw new Error(`Adaptive routing transform could not locate exactly one ${label}`);
  }
  return source.slice(0, first) + to + source.slice(first + from.length);
}

export function applyLunaAdaptiveTransforms(direction = "forward") {
  if (!["forward", "reverse"].includes(direction)) {
    throw new Error("Adaptive routing transform direction must be forward or reverse");
  }
  const transforms = direction === "forward" ? TRANSFORMS : [...TRANSFORMS].reverse();
  const cache = new Map();
  for (const transform of transforms) {
    const source = cache.has(transform.path)
      ? cache.get(transform.path)
      : readFileSync(transform.path, "utf8");
    const from = direction === "forward" ? transform.before : transform.after;
    const to = direction === "forward" ? transform.after : transform.before;
    cache.set(
      transform.path,
      replaceExact(source, from, to, `${direction} ${transform.label}`),
    );
  }
  for (const [path, source] of cache) writeFileSync(path, source, "utf8");
}

export const LUNA_ADAPTIVE_TRANSFORM_COUNT = TRANSFORMS.length;
